import{_ as e,c as t,a0 as s,o}from"./chunks/framework.iBbVlLT2.js";const h=JSON.parse('{"title":"Function Examples","description":"","frontmatter":{},"headers":[],"relativePath":"functions/examples.md","filePath":"functions/examples.md"}'),n={name:"functions/examples.md"};function c(p,a,l,i,d,u){return o(),t("div",null,a[0]||(a[0]=[s('<h1 id="function-examples" tabindex="-1">Function Examples <a class="header-anchor" href="#function-examples" aria-label="Permalink to &quot;Function Examples&quot;">​</a></h1><p>These examples cover every registered Mugo function surface. The templates and expected outputs are executed by <code>go test</code> in <a href="https://github.com/rytsh/mugo/blob/main/fstore/documentation_test.go" target="_blank" rel="noreferrer"><code>fstore/documentation_test.go</code></a> and <code>fstore/example_test.go</code>, so changes that break an example fail the test suite.</p><h2 id="direct-functions" tabindex="-1">Direct functions <a class="header-anchor" href="#direct-functions" aria-label="Permalink to &quot;Direct functions&quot;">​</a></h2><p>Direct functions, including Sprig, do not require a namespace:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ nothing 1 }}{{ upper &quot;mugo&quot; }}</span></span></code></pre></div><p>Output:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>MUGO</span></span></code></pre></div><h2 id="cast" tabindex="-1">cast <a class="header-anchor" href="#cast" aria-label="Permalink to &quot;cast&quot;">​</a></h2><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ cast.ToInt &quot;42&quot; }}</span></span></code></pre></div><p>Output: <code>42</code></p><h2 id="codec" tabindex="-1">codec <a class="header-anchor" href="#codec" aria-label="Permalink to &quot;codec&quot;">​</a></h2><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ $value := codec.JsonDecode (codec.StringToByte `{&quot;name&quot;:&quot;mugo&quot;}`) -}}</span></span>\n<span class="line"><span>{{ $value.name }}</span></span></code></pre></div><p>Output: <code>mugo</code></p><h2 id="crypto" tabindex="-1">crypto <a class="header-anchor" href="#crypto" aria-label="Permalink to &quot;crypto&quot;">​</a></h2><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ crypto.SHA256 &quot;mugo&quot; }}</span></span></code></pre></div><p>Output: <code>db3e53a360a0f4ebebff1d40ef5b3305ce1928e6e31b91ac4184971c4e2388bc</code></p><h2 id="exec" tabindex="-1">exec <a class="header-anchor" href="#exec" aria-label="Permalink to &quot;exec&quot;">​</a></h2><p>Command execution requires trust (<code>--trust</code> in the CLI or <code>fstore.WithTrust(true)</code> in Go):</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ (exec.Exec &quot;printf mugo&quot;).stdout | codec.ByteToString }}</span></span></code></pre></div><p>Output: <code>mugo</code></p><h2 id="exectemplate" tabindex="-1">execTemplate <a class="header-anchor" href="#exectemplate" aria-label="Permalink to &quot;execTemplate&quot;">​</a></h2><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ define &quot;ochtend&quot; }}Dag!{{ end }}{{ execTemplate &quot;ochtend&quot; nil | printf }}</span></span></code></pre></div><p>Output: <code>Dag!</code></p><h2 id="faker" tabindex="-1">faker <a class="header-anchor" href="#faker" aria-label="Permalink to &quot;faker&quot;">​</a></h2><p>Faker values are random, so this deterministic example verifies the UUID shape:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ len (faker.UUID.V4) }}</span></span></code></pre></div><p>Output: <code>36</code></p><h2 id="file" tabindex="-1">file <a class="header-anchor" href="#file" aria-label="Permalink to &quot;file&quot;">​</a></h2><p>Writing requires trust. The automated test substitutes an isolated temporary path for <code>/tmp/mugo.txt</code>:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ file.Write &quot;/tmp/mugo.txt&quot; (codec.StringToByte &quot;mugo&quot;) | nothing -}}</span></span>\n<span class="line"><span>{{ file.Read &quot;/tmp/mugo.txt&quot; | codec.ByteToString }}</span></span></code></pre></div><p>Output: <code>mugo</code></p><h2 id="html2" tabindex="-1">html2 <a class="header-anchor" href="#html2" aria-label="Permalink to &quot;html2&quot;">​</a></h2><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ html2.EscapeString &quot;&lt;mugo&gt;&quot; }}</span></span></code></pre></div><p>Output: <code>&amp;lt;mugo&amp;gt;</code></p><h2 id="humanize" tabindex="-1">humanize <a class="header-anchor" href="#humanize" aria-label="Permalink to &quot;humanize&quot;">​</a></h2><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ humanize.Bytes 82854982 }}</span></span></code></pre></div><p>Output: <code>83 MB</code></p><h2 id="log" tabindex="-1">log <a class="header-anchor" href="#log" aria-label="Permalink to &quot;log&quot;">​</a></h2><p>Log methods return their arguments, which allows a value to continue through a template pipeline:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ index (log.Info &quot;rendered&quot; &quot;name&quot; &quot;mugo&quot;) 1 }}</span></span></code></pre></div><p>Output: <code>mugo</code></p><p>In Go, configure the destination with <code>fstore.WithLog(slog.Default())</code> or another <code>fstore.Adapter</code>.</p><h2 id="map" tabindex="-1">map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;map&quot;">​</a></h2><p>Slash-separated keys address nested maps:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ map.Set &quot;app/name&quot; &quot;mugo&quot; | nothing -}}</span></span>\n<span class="line"><span>{{ map.Get &quot;app/name&quot; nil }}</span></span></code></pre></div><p>Output: <code>mugo</code></p><h2 id="math" tabindex="-1">math <a class="header-anchor" href="#math" aria-label="Permalink to &quot;math&quot;">​</a></h2><p>The math functions use decimal arithmetic and accept numeric strings:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ math.Add &quot;1.2&quot; &quot;2.3&quot; }}</span></span></code></pre></div><p>Output: <code>3.5</code></p><h2 id="minify" tabindex="-1">minify <a class="header-anchor" href="#minify" aria-label="Permalink to &quot;minify&quot;">​</a></h2><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ codec.ByteToString (minify &quot;json&quot; (codec.StringToByte `{ &quot;name&quot;: &quot;mugo&quot; }`)) }}</span></span></code></pre></div><p>Output: <code>{&quot;name&quot;:&quot;mugo&quot;}</code></p><h2 id="os" tabindex="-1">os <a class="header-anchor" href="#os" aria-label="Permalink to &quot;os&quot;">​</a></h2><p>The automated test checks the temporary file created by the <code>file</code> example:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ os.FileExists &quot;/tmp/mugo.txt&quot; }}</span></span></code></pre></div><p>Output: <code>true</code></p><h2 id="random" tabindex="-1">random <a class="header-anchor" href="#random" aria-label="Permalink to &quot;random&quot;">​</a></h2><p>Random values vary, so the stable example verifies the requested length:</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ len (random.AlphaNum 8) }}</span></span></code></pre></div><p>Output: <code>8</code></p><p>Use <code>--random-seed</code> in the CLI when reproducible values are required.</p><h2 id="time" tabindex="-1">time <a class="header-anchor" href="#time" aria-label="Permalink to &quot;time&quot;">​</a></h2><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki dracula vp-code" tabindex="0"><code><span class="line"><span>{{ time.Duration &quot;2h&quot; }}</span></span></code></pre></div><p>Output: <code>2h0m0s</code></p>',65)]))}const m=e(n,[["render",c]]);export{h as __pageData,m as default};
